/**
 * A {@link Loader} for processing executable and linking files (ELF).
 */
public class ElfLoader : AbstractLibrarySupportLoader {

	public static string ELF_NAME = "Executable and Linking Format (ELF)";

	public static string ELF_ENTRY_FUNCTION_NAME = "entry";

	public static string ELF_FILE_TYPE_PROPERTY = "ELF File Type";
	public static string ELF_ORIGINAL_IMAGE_BASE_PROPERTY = "ELF Original Image Base";
	public static string ELF_PRELINKED_PROPERTY = "ELF Prelinked";

	public static string ELF_SOURCE_FILE_PROPERTY_PREFIX = "ELF Source File ["; // followed by "#]"

	/**
	 * Getter for the {@link #ELF_ORIGINAL_IMAGE_BASE_PROPERTY} property.
	 * 
	 * @param program Ghidra program that has the property to get
	 * @return Long value of the original image base, or null if the property is not present
	 */
	public static Long getElfOriginalImageBase(Program program) {
		Options props = program.getOptions(Program.PROGRAM_INFO);
		string oibStr = props.getString(ElfLoader.ELF_ORIGINAL_IMAGE_BASE_PROPERTY, null);
		return (oibStr != null) ? NumericUtilities.parseHexLong(oibStr) : null;
	}

	/**
	 * {@return true if the specified program was loaded via the ELF loader}
	 * @param program {@link Program}
	 */
	public static bool isElf(Program program) {
		return isElf(program.getExecutableFormat());
	}

	/**
	 * {@return true if the specified executable format string matches the ELF loader}
	 * @param executableFormatString executable format string retrieved from a program's properties
	 */
	public static bool isElf(string executableFormatString) {
		return executableFormatString != null && ELF_NAME.equals(executableFormatString);
	}

	public ElfLoader() {
	}

	/* @Override */
	public List<Option> getDefaultOptions(ByteProvider provider, LoadSpec loadSpec,
			DomainObject domainObject, bool loadIntoProgram, bool mirrorFsLayout) {

		// NOTE: add-to-program is not supported

		List<Option> options = base.getDefaultOptions(provider, loadSpec, domainObject,
			loadIntoProgram, mirrorFsLayout);

		try {
			ElfLoaderOptionsFactory.addOptions(options, provider, loadSpec);
		}
		catch (Exception e) {
			Msg.error(this, "Error while generating Elf import options", e);
			// ignore here, will catch later
		}

		return options;
	}

	/* @Override */
	public string validateOptions(ByteProvider provider, LoadSpec loadSpec, List<Option> options,
			Program program) {
		if (options != null) {
			string validationErrorStr =ElfLoaderOptionsFactory.validateOptions(loadSpec, options);
			if (validationErrorStr != null) {
				return validationErrorStr;
			}
		}

		return base.validateOptions(provider, loadSpec, options, program);
	}

	/* @Override */
	public Collection<LoadSpec> findSupportedLoadSpecs(ByteProvider provider)
    {
		List<LoadSpec> loadSpecs = new();

		try {
			ElfHeader elf = new ElfHeader(provider, null);

			Set<QueryResult> results = new();
			string machine = elf.getMachineName();
			string compiler = detectCompilerName(elf);
			if (compiler != null) {
				results.addAll(QueryOpinionService.query(getName(), machine, compiler));
			}
			results.addAll(QueryOpinionService.query(getName(), machine, elf.getFlags()));
			foreach (QueryResult result in results) {
				bool add = true;
				// Some languages are defined with sizes smaller than 32
				if (elf.is32Bit() && result.pair.getLanguageDescription().getSize() > 32) {
					add = false;
				}
				if (elf.is64Bit() && result.pair.getLanguageDescription().getSize() <= 32) {
					add = false;
				}
				if (elf.isLittleEndian() &&
					result.pair.getLanguageDescription().getEndian() != Endian.LITTLE) {
					add = false;
				}
				if (elf.isBigEndian() &&
					result.pair.getLanguageDescription().getEndian() != Endian.BIG) {
					add = false;
				}
				if (add) {
					loadSpecs.add(new LoadSpec(this, 0, result));
				}
			}
			if (loadSpecs.isEmpty()) {
				loadSpecs.add(new LoadSpec(this, 0, true));
			}
		}
		catch (ElfException e) {
			// not a problem, it's not an elf
		}

		return loadSpecs;
	}

	/* @Override */
	public void load(Program program, ImporterSettings settings)
    {

		try {
			ElfHeader elf =
				new ElfHeader(settings.provider(), msg => settings.log().appendMsg(msg));
			ElfProgramBuilder.loadElf(elf, program, settings.options(), settings.log(),
				settings.monitor());
		}
		catch (ElfException e) {
			throw new IOException(e.getMessage());
		}
	}

	/* @Override */
	protected void postLoadProgramFixups(List<Loaded<Program>> loadedPrograms,
			ImporterSettings settings)
    {
		base.postLoadProgramFixups(loadedPrograms, settings);

		ProjectData projectData =
			settings.project() != null ? settings.project().getProjectData() : null;
		using (ExternalSymbolResolver esr =
			new ExternalSymbolResolver(projectData, settings.monitor()))
{
			loadedPrograms.forEach(p => esr.addProgramToFixup(p));
			esr.fixUnresolvedExternalSymbols();
			esr.logInfo(settings.log().appendMsg, true);
		}
	}

	/* @Override */
	public string getName() {
		return ELF_NAME;
	}

	/* @Override */
	public Collection<string> getAssociatedFileExtensions() {
		return List.of("so", "o");
	}

	/**
	 * Attempts to detect a more specific compiler from the ELF
	 * 
	 * @param elf The {@link ElfHeader}
	 * @return The detected compiler name, or {@code null} if one couldn't be detected
	 * @throws IOException if an IO-related error occurred
	 */
	private string detectCompilerName(ElfHeader elf)
    {
		elf.parseSectionHeaders();
		List<string> sectionNames = Arrays.stream(elf.getSections())
				.map(ElfSectionHeader.getNameAsString)
				.toList();
		if (GoRttiMapper.hasGolangSections(sectionNames)) {
			return GoConstants.GOLANG_CSPEC_NAME;
		}
		return null;
	}
}
